  FT["SG-H2182"] = {"id":"SG-H2182","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S257-2010?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（经济发展与技术开发利息及其他付款豁免）公告 2010","en":"Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) Notification 2010","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S257-2010","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2182-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1.—(1) This Notification may be cited as the Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) Notification 2010 and shall be deemed to have come into operation on 1st September 2009.\n(2) This Notification shall remain in operation for a period of 10 years until 31st August 2019."}},{"id":"SG-H2182-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) There shall be exempt from tax the upfront fees and interest payable by BOC Aviation Pte. Ltd. to the following banks, under the Loan Agreements dated 25th August 2009 in respect of one Boeing 737-800 aircraft and one Boeing 737-700 aircraft with Manufacturer’s Serial Numbers 36690 and 36691, respectively:\n(a)Bank of China Limited, Tokyo Branch;\n(b)Bank of China Limited, Macau Branch; and\n(c)Bank of China Limited, Sydney Branch.\n(2) The exemption is subject to the terms and conditions specified in the letter of approval dated 29th September 2009 addressed to BOC Aviation Pte. Ltd."}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) Notification 2010","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2183"] = {"id":"SG-H2183","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S206-2011?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（经济发展与技术开发利息及其他付款豁免）公告 2011","en":"Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) Notification 2011","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S206-2011","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2183-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification may be cited as the Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) Notification 2011 and shall be deemed to have come into operation on 1st January 2009."}},{"id":"SG-H2183-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) There shall be exempt from tax the interest payable by a shipping enterprise on an approved loan taken from a lender that is neither a resident nor permanent establishment in Singapore, being a loan taken for the acquisition by the enterprise of —\n(a)one or more ships registered or provisionally registered, or to be registered or provisionally registered, under the Merchant Shipping Act (Cap. 179); or\n(b)all the shares of a special purpose vehicle that has sole legal and beneficial ownership of one or more ships registered or provisionally registered under the Merchant Shipping Act, or that is to have sole legal and beneficial ownership of one or more ships to be registered or provisionally registered under that Act,\nsubject to such conditions as may be imposed by the Minister and notified to the enterprise.\n(2) The Minister may impose different conditions for different classes of shipping enterprises or in different circumstances.\n(3) In this paragraph —\n“approved loan” means a loan or other arrangement similar in nature to a loan in a currency other than Singapore dollar, that is approved between 1st January 2009 and 31st May 2011 for the purposes of sub-paragraph (1) by the Minister;\n“interest” includes any front-end and commitment fee for the loan, and any interest rate swap payments and currency swap payments in connection with the loan;\n“shipping enterprise” means a company that owns or operates one or more ships;\n“special purpose vehicle” means a company whose only business is or is to be the owning or operating of the ship or ships referred to in paragraph 2(1)(b).\n(4) In this paragraph, a ship shall not be regarded as registered or provisionally registered under the Merchant Shipping Act (Cap. 179) if its registry under that Act is closed or deemed to be closed or is suspended."}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) Notification 2011","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2184"] = {"id":"SG-H2184","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S72-2012?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"所得税（经济与技术发展利息及其他付款豁免）公告 2012","en":"Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) Notification 2012","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S72-2012","completenessNote":"全文，共 3 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2184-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification may be cited as the Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) Notification 2012 and shall be deemed to have come into operation on 1st April 2011."}},{"id":"SG-H2184-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definitions"},"text":{"en":"2. In this Notification —\n“bank” means a bank that holds a bank licence under section 7 or 79 of the Banking Act 1970;\n“finance company” means a finance company licensed under the Finance Companies Act 1967;\n“merchant bank” means a merchant bank that, under the Banking Act 1970 —\n(a)holds a merchant bank licence; or\n(b)is treated as having been granted a merchant bank licence;\n“qualifying payment” means any of the following which is deemed under section 12(6) of the Act to be derived from Singapore:\n(a)any interest, commission, fee or other payment;\n(b)any income derived from loans.\n[S 330/2024 wef 15/04/2024]"}},{"id":"SG-H2184-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Exemption"},"text":{"en":"3.—(1) Subject to sub-paragraphs (3) and (4), a qualifying payment which is made to a person referred to in sub-paragraph (6) by —\n(a)a bank;\n[S 330/2024 wef 15/04/2024]\n(aa)[Deleted by S 330/2024 wef 15/04/2024]\n(b)a merchant bank; or\n[S 330/2024 wef 15/04/2024]\n(c)a finance company,\n[S 330/2024 wef 15/04/2024]\nshall be exempt from tax if the qualifying payment —\n(i)is liable to be made during the period from 1st April 2011 to 31 December 2031 (both dates inclusive) under —\n[S 937/2022 wef 01/04/2021]\n(A)a contract which took effect before 1st April 2011;\n(B)a contract which is extended or renewed, where the extension or renewal took effect before 1st April 2011; or\n(C)a debt security which was issued before 1st April 2011;\n[S 587/2026 wef 09/09/2026]\n(ii)is liable to be made under a contract which takes effect on a date which falls within the period from 1st April 2011 to 31 December 2031 (both dates inclusive);\n[S 937/2022 wef 01/04/2021]\n[S 587/2026 wef 09/09/2026]\n(iii)is liable to be made —\n(A)under a contract which is extended or renewed, where the extension or renewal takes effect on a date which falls within the period from 1st April 2011 to 31 December 2031 (both dates inclusive); and\n[S 937/2022 wef 01/04/2021]\n[S 587/2026 wef 09/09/2026]\n(B)on or after the date on which such extension or renewal takes effect;\n[S 330/2024 wef 04/11/2022]\n(iiia)is liable to be made —\n(A)under a contract which is varied, where the variation takes effect on a date which falls within the period from 4 November 2022 to 31 December 2031 (both dates inclusive); and\n[S 587/2026 wef 09/09/2026]\n(B)on or after the date on which the variation takes effect; or\n[S 330/2024 wef 04/11/2022]\n(iv)is liable to be made under a debt security which is issued on a date which falls within the period from 1st April 2011 to 31 December 2031 (both dates inclusive).\n[S 937/2022 wef 01/04/2021]\n[S 937/2022 wef 31/12/2021]\n[S 330/2024 wef 15/04/2024]\n[S 587/2026 wef 09/09/2026]\n(2) Subject to sub-paragraphs (3) and (5), a qualifying payment which is made to a person referred to in sub-paragraph (6) by a person (referred to in this Notification as an approved payer) who —\n(a)holds a capital markets services licence under the Securities and Futures Act 2001 for dealing in capital markets products and advising on corporate finance;\n[S 330/2024 wef 08/10/2018]\n[S 937/2022 wef 31/12/2021]\n(b)is involved or will be involved in the underwriting of debt or equity issuances; and\n(c)is approved for the purposes of this Notification by the Minister or an authorised body, subject to such conditions as the Minister or authorised body, as the case may be, may impose,\nshall be exempt from tax if the qualifying payment —\n(i)is liable to be made during the period from the date on which the approval referred to in sub-paragraph (c) is given (referred to in this Notification as the approval date) to 31 December 2031 (both dates inclusive) under —\n[S 937/2022 wef 01/04/2021]\n(A)a contract which took effect before the approval date;\n(B)a contract which is extended or renewed, where the extension or renewal took effect before the approval date;\n[S 330/2024 wef 04/11/2022]\n(BA)a contract which is varied, where the variation took effect before the approval date, being a date that is on or after 4 November 2022; or\n[S 330/2024 wef 04/11/2022]\n(C)a debt security which was issued before the approval date;\n[S 587/2026 wef 09/09/2026]\n(ii)is liable to be made under a contract which takes effect on a date which falls within the period from the approval date to 31 December 2031 (both dates inclusive);\n[S 937/2022 wef 01/04/2021]\n[S 587/2026 wef 09/09/2026]\n(iii)is liable to be made —\n(A)under a contract which is extended or renewed, where the extension or renewal takes effect on a date which falls within the period from the approval date to 31 December 2031 (both dates inclusive); and\n[S 937/2022 wef 01/04/2021]\n[S 587/2026 wef 09/09/2026]\n(B)on or after the date on which such extension or renewal takes effect;\n[S 330/2024 wef 04/11/2022]\n(iiia)is liable to be made —\n(A)under a contract which is varied, where the variation takes effect on a date which falls within the period from 4 November 2022 or the approval date (whichever is later) to 31 December 2031 (both dates inclusive); and\n[S 587/2026 wef 09/09/2026]\n(B)on or after the date on which the variation takes effect; or\n[S 330/2024 wef 04/11/2022]\n(iv)is liable to be made under a debt security which is issued on a date which falls within the period from the approval date to 31 December 2031 (both dates inclusive).\n[S 937/2022 wef 01/04/2021]\n[S 937/2022 wef 06/12/2022]\n[S 330/2024 wef 15/04/2024]\n[S 587/2026 wef 09/09/2026]\n(3) The exemptions referred to in sub-paragraphs (1) and (2) shall not apply to any qualifying payment made by a bank, merchant bank, finance company or an approved payer, as the case may be, in connection with an arrangement referred to in section 33(1) of the Act.\n[S 330/2024 wef 15/04/2024]\n(4) Sub-paragraph (1) does not apply to any qualifying payment liable to be made —\n(a)under a contract mentioned in sub-paragraph (1)(ii), (iii) or (iiia), that is varied with effect from a date on or after 1 January 2032; and\n[S 587/2026 wef 09/09/2026]\n(b)on or after the date on which such variation takes effect.\n[S 330/2024 wef 15/04/2024]\n(5) Sub-paragraph (2) does not apply to any qualifying payment liable to be made —\n(a)under a contract mentioned in sub-paragraph (2)(ii), (iii) or (iiia), that is varied with effect from a date on or after 1 January 2032; and\n[S 587/2026 wef 09/09/2026]\n(b)on or after the date on which such variation takes effect.\n[S 330/2024 wef 15/04/2024]\n(6) The person referred to in sub-paragraphs (1) and (2), to whom the qualifying payment is made, is —\n(a)a person who is not resident in Singapore and who does not have a permanent establishment in Singapore; or\n(b)a person who is not resident in Singapore and who carries on any operation in Singapore through a permanent establishment in Singapore, where —\n(i)the contract under which the qualifying payment is made is not entered into through that operation; or\n(ii)the debt security under which the qualifying payment is made is not acquired by that person through that operation.\n[S 330/2024 wef 15/04/2024]"}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) Notification 2012","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2185"] = {"id":"SG-H2185","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S5-2013?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"所得税（经济与技术发展利息及其他付款豁免）公告 2013","en":"Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) Notification 2013","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S5-2013","completenessNote":"全文，共 3 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2185-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification may be cited as the Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) Notification 2013 and shall be deemed to have come into operation on 20th May 2012."}},{"id":"SG-H2185-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definitions"},"text":{"en":"2. In this Notification —\n“Authority” means the Monetary Authority of Singapore established under section 3 of the Monetary Authority of Singapore Act 1970;\n[S 328/2024 wef 31/12/2021]\n“financial derivatives” means derivatives the payoffs of which are linked, whether in whole or in part, to the payoffs or performance of any financial assets, securities, financial instruments or indices, but does not include derivatives the payoffs of which are linked wholly to the payoffs or performance of commodities;\n“financial institution” means any institution licensed or approved by the Authority, or exempt from such licensing or approval, under any Act administered by the Authority, and includes an approved Finance and Treasury Centre referred to in section 43E of the Act.\n[S 328/2024 wef 31/12/2021]\n[Deleted by S 328/2024 wef 04/11/2022]"}},{"id":"SG-H2185-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Exemption"},"text":{"en":"3.—(1) There shall be exempt from tax any payment made by a financial institution to a person who is not resident in Singapore and who does not have a permanent establishment in Singapore —\n(a)on over-the-counter financial derivatives, where the payment is liable to be made during the period from 20 May 2012 to 31 December 2031 (both dates inclusive) under —\n(i)a contract for such derivatives which took effect before 15th February 2007; or\n(ii)a contract for such derivatives which is extended or renewed, where the extension or renewal took effect before 15th February 2007;\n[S 328/2024 wef 04/11/2022]\n[S 575/2021 wef 01/04/2021]\n[S 587/2026 wef 09/09/2026]\n(b)on over-the-counter financial derivatives, where the payment is liable to be made under —\n(i)a contract for such derivatives which takes effect during the period from 20 May 2012 to 31 December 2031 (both dates inclusive); or\n[S 575/2021 wef 01/04/2021]\n[S 587/2026 wef 09/09/2026]\n(ii)a contract for such derivatives which is extended or renewed, where the extension or renewal takes effect during the period from 20 May 2012 to 31 December 2031 (both dates inclusive); and\n[S 575/2021 wef 01/04/2021]\n[S 328/2024 wef 04/11/2022]\n[S 587/2026 wef 09/09/2026]\n(c)on over-the-counter financial derivatives, where the payment is liable to be made under —\n(i)a contract for such derivatives which is varied, where the variation takes effect during the period from 4 November 2022 to 31 December 2031 (both dates inclusive); and\n[S 587/2026 wef 09/09/2026]\n(ii)the payment is made on or after the date on which the variation takes effect.\n[S 328/2024 wef 04/11/2022]\n[S 575/2021 wef 01/04/2021]\n(1A) The exemption under sub-paragraph (1) also applies where the payment by the financial institution is made to a person who is not resident in Singapore and who carries on any operation in Singapore through a permanent establishment in Singapore, where the payment is made under a contract for over-the-counter financial derivatives not entered into through that operation.\n[S 575/2021 wef 01/04/2021]\n(1B) However, the exemption under sub-paragraph (1) does not apply to a payment made on over-the-counter financial derivatives, where the payment is liable to be made —\n(a)under a contract for such derivatives mentioned in sub-paragraph (1)(b) or (c) that is varied with effect from a date on or after 1 January 2032; and\n[S 587/2026 wef 09/09/2026]\n(b)on or after the date on which the variation takes effect.\n[S 328/2024 wef 15/04/2024]\n(2) The exemption in respect of any payment under sub‑paragraph (1) or (1A) is subject to the following conditions:\n(a)for a first payment on any over-the-counter financial derivatives by a financial institution (not being an approved Finance and Treasury Centre under section 43E of the Act) that is exempt from licensing or approval under any Act administered by the Authority, the financial institution shall submit to the Comptroller on or before the date of such payment —\n(i)a declaration that it is exempt from licensing or approval under any Act administered by the Authority from a specified date under a specified provision of the Act; and\n(ii)an undertaking —\n(A)to notify the Comptroller immediately when it ceases to be a financial institution (not being an approved Finance and Treasury Centre under section 43E of the Act) that is exempt from licensing or approval under any Act administered by the Authority; and\n(B)to comply with the obligations under sections 45 and 45A of the Act; and\n[S 328/2024 wef 31/12/2021]\n(b)for a payment on any over-the-counter financial derivatives, where the contract is entered into with a related party of the financial institution —\n(i)the transaction was carried out at arm’s length; and\n(ii)the financial institution shall submit a declaration to the Comptroller that the transaction referred to in sub‑paragraph (i) was carried out at arm’s length, together with its tax return for the year of assessment for the basis period during which the payment was made.\n[S 575/2021 wef 01/04/2021]"}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) Notification 2013","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2186"] = {"id":"SG-H2186","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S57-2018?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（经济发展与技术开发利息及其他付款豁免）公告 2018","en":"Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) Notification 2018","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S57-2018","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2186-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) Notification 2018 and is deemed to have come into operation on 11 December 2017."}},{"id":"SG-H2186-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) The interest payable during the period starting on 11 December 2017 and ending on 11 December 2022, by Eterna Capital Pte. Ltd. to any person who is not resident in Singapore, under the Indenture dated 11 December 2017, in respect of the Series A and B guaranteed senior secured notes which mature in 2022, is exempt from tax.\n(2) The interest payable during the period starting on 11 December 2017 and ending on 11 December 2024, by Innovate Capital Pte. Ltd. to any person who is not resident in Singapore, under the Trust Deed dated 11 December 2017, in respect of the convertible bonds with a guaranteed interest rate of 6% per annum and which mature in 2024, is exempt from tax.\n(3) The exemptions under sub‑paragraphs (1) and (2) are subject to the following conditions:\n(a)the person to whom the interest is payable did not use any funds obtained through the operation of any permanent establishment in Singapore to purchase the notes or bonds (as the case may be);\n(b)the terms and conditions specified in the letter of approval dated 17 November 2017 addressed to Withers KhattarWong, legal representative of PT Bumi Resources Tbk, are satisfied."}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) Notification 2018","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2187"] = {"id":"SG-H2187","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S175-2019?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（经济发展与技术开发利息及其他付款豁免）公告 2019","en":"Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) Notification 2019","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S175-2019","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2187-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) Notification 2019 and is deemed to have come into operation on 30 June 2018."}},{"id":"SG-H2187-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) The interest of US$295,238.34, commitment fee of US$7,875.00 and arrangement fee of US$70,875.00 payable by Nordic Aviation Leasing Twenty Three Pte Ltd to Flip No. 121 Co., Ltd during the period starting on 30 June 2018 and ending on 30 September 2018, under an aircraft lease agreement dated 22 May 2018 in respect of the leasing of aircraft “MSN 4580”, are exempt from tax.\n(2) The interest of US$228,449.38, commitment fee of US$19,687.50 and arrangement fee of US$70,875.00 payable by Nordic Aviation Leasing Twenty Four Pte Ltd to Flip No. 150 Co., Ltd during the period starting on 30 June 2018 and ending on 30 September 2018, under an aircraft lease agreement dated 14 June 2018 in respect of the leasing of aircraft “MSN 4582”, are exempt from tax.\n(3) The exemptions under sub-paragraphs (1) and (2) are subject to the conditions specified in the letter of approval dated 24 December 2018 issued by the Ministry of Finance and addressed to Nordic Aviation Capital Pte Ltd."}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Interest and Other Payments for Economic and Technological Development) Notification 2019","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2188"] = {"id":"SG-H2188","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S636-2016?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"所得税（经济发展与技术开发贷款及融资租赁的利息及其他付款豁免）（第 4 号）公告 2016","en":"Income Tax (Exemption of Interest and Other Payments on Economic and Technological Development Loans and Finance Leases) (No. 4) Notification 2016","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S636-2016","completenessNote":"全文，共 6 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2188-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Exemption of Interest and Other Payments on Economic and Technological Development Loans and Finance Leases) (No. 4) Notification 2016 and is deemed to have come into operation on 17 February 2012.\n[S 338/2021 wef 24/02/2015]"}},{"id":"SG-H2188-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"General definitions"},"text":{"en":"2.—(1) In this Notification, unless the context otherwise requires —\n“approved container investment enterprise” has the same meaning as in section 43P of the Act, and includes a partnership approved by the Minister (or such person as the Minister may appoint) under section 43P of the Act as applied by section 36 of the Act;\n[S 307/2024 wef 31/12/2021]\n“Authority” means the Maritime and Port Authority of Singapore established by section 4 of the Maritime and Port Authority of Singapore Act 1996;\n[S 338/2021 wef 24/02/2015]\n[S 307/2024 wef 31/12/2021]\n“container” and “intermodal equipment” have the same meanings as in section 43P(7) of the Act;\n[S 307/2024 wef 31/12/2021]\n“finance lease”, in relation to one or more containers, means a lease of the container or containers (including any arrangement or agreement in connection with the lease) which has the effect of transferring substantially the obsolescence, risks or rewards incidental to the ownership of the container or containers to the lessee;\n[S 338/2021 wef 24/02/2015]\n“original container” means any of the containers mentioned in paragraph 3(2)(a), (b), (ba), (bb) or (c) or 5(1), but excludes a container that replaces another container under the terms of the agreement for the applicable loan or applicable finance lease (as the case may be) after that other container is disposed of or lost at sea;\n[S 338/2021 wef 24/02/2015]\n“qualifying payment”, in relation to an applicable loan or applicable finance lease, means any of the following payments made in connection with the applicable loan or applicable finance lease:\n(a)either —\n(i)in the case of an applicable loan —interest; or\n(ii)in the case of an applicable finance lease — any payment liable to be made by the lessee to the lessor under the finance lease that is not attributable to the repayment of principal;\n(b)front-end fees;\n(c)commitment fees;\n(d)interest rate swap payments;\n(e)currency swap payments;\n(f)arranger fees;\n(g)arrangement fees;\n(h)retainer fees;\n(i)agency fees;\n(j)security trustee fees;\n[S 338/2021 wef 24/02/2015]\n“specified person”, in relation to an applicable loan or applicable finance lease, means a person who —\n(a)is not resident in Singapore; and\n(b)either —\n(i)does not (alone or in association with others) carry on a business in Singapore, and does not have a permanent establishment in Singapore; or\n(ii)carries on a business in Singapore (alone or in association with others) or has a permanent establishment in Singapore, but no arrangement, management or service relating to the applicable loan or applicable finance lease is made or performed through that business or that permanent establishment.\n[S 338/2021 wef 24/02/2015]\n[S 307/2024 wef 12/04/2024]\n(2) For the purpose of this Notification, a reference in the definition of “approved container investment enterprise” to such person as the Minister may appoint is, on or after 12 April 2024, to an authorised body.\n[S 307/2024 wef 12/04/2024]"}},{"id":"SG-H2188-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Meaning of “applicable loan”"},"text":{"en":"3.—(1) In this Notification, an applicable loan is a loan (or other arrangement similar to a loan) obtained on or before 31 May 2021 by an approved container investment enterprise —\n(a)that is obtained solely for a purpose specified in sub-paragraph (2); or\n(b)where the purposes for which it is obtained include any one or more purposes specified in sub-paragraph (2).\n[S 338/2021 wef 17/02/2012]\n[S 338/2021 wef 24/02/2015]\n(2) The purposes mentioned in sub‑paragraph (1) are —\n(a)the acquisition by the enterprise of one or more containers;\n(b)the acquisition by the enterprise of all the shares of a special purpose vehicle that has sole legal and beneficial ownership of one or more containers;\n[S 338/2021 wef 24/02/2015]\n(ba)the acquisition by the enterprise of all the shares issued by a special purpose vehicle (called in this paragraph the additional shares) where —\n(i)the enterprise has sole legal and beneficial ownership of all the shares of the special purpose vehicle immediately before the additional shares are issued;\n(ii)the acquisition of the additional shares is for the purpose of financing the acquisition by the special purpose vehicle of one or more containers; and\n(iii)the special purpose vehicle has sole legal and beneficial ownership of each container mentioned in sub-paragraph (ii);\n[S 338/2021 wef 24/02/2015]\n(bb)the grant of a loan by the enterprise to a special purpose vehicle where —\n(i)the enterprise has sole legal and beneficial ownership of all the shares of the special purpose vehicle;\n(ii)the loan is granted by the enterprise for the purpose of financing the acquisition by the special purpose vehicle of one or more containers; and\n(iii)the special purpose vehicle has sole legal and beneficial ownership of each container mentioned in sub-paragraph (ii); or\n[S 338/2021 wef 24/02/2015]\n(c)the financing of qualifying payments on a previous loan that is obtained by the enterprise solely for any of the following purposes, or where the purposes for which it is obtained by the enterprise include any one or more of the following:\n(i)the acquisition of one or more containers;\n(ii)the acquisition of all the shares of a special purpose vehicle that has sole legal and beneficial ownership of one or more containers;\n(iii)the acquisition of the additional shares mentioned in sub-paragraph (ba) for the purpose of financing the acquisition of one or more containers mentioned in that sub-paragraph in the circumstances mentioned in sub-paragraph (ba)(i), (ii) and (iii);\n(iv)the grant of a loan by the enterprise in connection with the acquisition of one or more containers mentioned in sub-paragraph (bb) in the circumstances mentioned in sub-paragraph (bb)(i), (ii) and (iii).\n[S 338/2021 wef 24/02/2015]\n(2A) For the purposes of sub-paragraph (2)(b), (ba), (bb) and (c)(ii), any treasury share in a special purpose vehicle is to be disregarded when determining whether an approved container investment enterprise —\n(a)has sole legal and beneficial ownership of all the shares in the special purpose vehicle; or\n(b)acquires all the shares issued by the special purpose vehicle.\n[S 338/2021 wef 24/02/2015]\n(3) A reference to the acquisition of one or more containers in the provision in the first column of the following table includes any one or more of the activities mentioned in sub-paragraph (3A) if (and only if) the circumstance in the second column of the table corresponding to that provision exists:\nFirst column\nSecond column\n(a)Sub-paragraph (2)(a) or (c)(i)\nThe loan or previous loan (as the case may be) obtained by the container investment enterprise is for both the acquisition of the container or containers by the enterprise and the activity or activities\n(b)Sub-paragraph (2)(ba)(ii) or (c)(iii)\nThe acquisition by the container investment enterprise of the additional shares in the special purpose vehicle is for both the acquisition of the container or containers by the special purpose vehicle and the activity or activities\n(c)Sub-paragraph (2)(bb)(ii) or (c)(iv)\nThe loan granted by the container investment enterprise to the special purpose vehicle is for both the acquisition of the container or containers by the special purpose vehicle and the activity or activities.\n[S 338/2021 wef 24/02/2015]\n(3A) For the purposes of sub-paragraph (3), the activities are as follows:\n(a)the purchase or installation of any equipment within or on any of the containers;\n(b)the inspection of any of the containers before accepting its delivery, and the obtaining of any report of such inspection;\n(c)the purchase of any intermodal equipment.\n[S 338/2021 wef 24/02/2015]\n(4) In this paragraph, a special purpose vehicle is a company —\n(a)that is incorporated for the purpose of owning or both owning and leasing —\n(i)any container; or\n(ii)any container and any intermodal equipment; or\n(b)whose only business is the owning or both the owning and leasing of —\n(i)any container; or\n(ii)any container and any intermodal equipment.\n[S 338/2021 wef 24/02/2015]\n(5) In this Notification, a reference to an applicable loan obtained by an approved container investment enterprise includes a reference to a loan obtained by the enterprise before it is approved as such."}},{"id":"SG-H2188-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Exemption in relation to applicable loan"},"text":{"en":"4.—(1) Subject to sub-paragraphs (1A) to (6) and the conditions imposed by the Minister under section 13(4) of the Act —\n(a)a qualifying payment that an approved container investment enterprise is liable to make before 24 February 2015 to a specified person under an agreement for an applicable loan is exempt from tax if (and only if) the applicable loan is for a purpose mentioned in paragraph 3(2)(a), (b) or (c)(i) or (ii); and\n(b)a qualifying payment that an approved container investment enterprise is liable to make on or after 24 February 2015 to a specified person under an agreement for an applicable loan is exempt from tax.\n[S 338/2021 wef 24/02/2015]\n[S 338/2021 wef 18/05/2021]\n(1A) Where the applicable loan is obtained for more than one purpose, including a purpose that is not specified in paragraph 3(2), the exemption in sub-paragraph (1) applies only to the amount of the qualifying payment derived by the formula where —\n(a)A is the principal of the applicable loan;\n(b)B is that part of the principal of the applicable loan that is not attributable to any purpose specified in paragraph 3(2); and\n(c)C is the qualifying payment.\n[S 338/2021 wef 18/05/2021]\n(2) For the purposes of sub-paragraphs (1) and (1A), a qualifying payment in relation to an applicable loan excludes interest on that part of the principal of the loan that is capitalised interest on the loan.\n[S 338/2021 wef 18/05/2021]\n(3) Where an applicable loan is obtained by the enterprise for the purpose of financing qualifying payments on a previous loan mentioned in paragraph 3(2)(c), the exemption under sub‑paragraph (1) does not apply to interest on any part of the principal of the applicable loan that is used to finance interest on any part of the principal of the previous loan that is capitalised interest on the previous loan.\n(4) The exemption under sub-paragraph (1) does not apply to any payment or part of any payment liable to be made under a loan obtained before 24 February 2015, being a payment or part of a payment that is exempt from tax under any other exemption granted under the Act or any subsidiary legislation made under the Act.\n[S 338/2021 wef 24/02/2015]\n(5) The exemption under sub‑paragraph (1) only applies to a qualifying payment liable to be made —\n(a)at any time on or after the date the enterprise makes a declaration, in relation to the applicable loan, to the Authority, in the form specified by the Authority for the purposes of this sub‑paragraph; or\n[S 338/2021 wef 24/02/2015]\n(b)if the declaration is made on or before the 15th day of a month, at any time on or after the first day of the previous month.\n(6) The exemption under sub‑paragraph (1) does not apply to any qualifying payment liable to be made —\n(a)after the day that any original container is disposed of or is lost at sea, unless the terms of the agreement for the applicable loan —\n(i)require that all original containers disposed of and lost at sea be replaced in the event that the value of such containers exceeds a sum stipulated in the agreement; or\n(ii)require the repayment of that part of the principal of the loan attributable to the cost of acquiring all original containers disposed of and lost at sea in the event that the value of such containers exceeds a sum stipulated in the agreement;\n(b)after the day that the enterprise disposes of any share in the special purpose vehicle, if the loan is for a purpose mentioned in paragraph 3(2)(b), (ba), (bb) or (c)(ii), (iii) or (iv); or\n[S 338/2021 wef 24/02/2015]\n(c)on or after the day that the approval of the approved container investment enterprise as such is revoked or withdrawn.\n(7) Where —\n(a)sub‑paragraph (1) has operated to exempt from tax any qualifying payment liable to be made under an agreement for an applicable loan mentioned in that sub‑paragraph; and\n(b)the term of the approval of the approved investment container enterprise as such subsequently expires,\nthen any qualifying payment liable to be made under that agreement by the enterprise on or after the date of the expiry to a person mentioned in that sub‑paragraph, is also exempt from tax.\n(8) The exemption under sub‑paragraph (7) is subject to the conditions mentioned in sub‑paragraph (1) and to sub-paragraphs (1A), (3), (4) and (6), and for this purpose those sub‑paragraphs apply as if a reference to an approved container investment enterprise were a reference to a container investment enterprise.\n[S 338/2021 wef 24/02/2015]\n[S 338/2021 wef 18/05/2021]"}},{"id":"SG-H2188-A5","no":5,"noLabel":{"en":"5."},"heading":{"en":"Meaning of “applicable finance lease”"},"text":{"en":"5.—(1) In this Notification, an applicable finance lease is a lease of one or more containers (at least one of which is a container within the meaning of “container” in section 43P(7) of the Act) under a finance lease entered into before 12 December 2018 that is treated as a sale pursuant to regulations made under section 10C of the Act.\n[S 307/2024 wef 31/12/2021]\n(2) The reference in sub-paragraph (1) to a lease of one or more containers under a finance lease includes any one or both of the following activities if (and only if) the finance lease is for both the leasing of the container or containers and the activity or activities:\n(a)the leasing of any equipment installed or to be installed within or on any of the containers;\n(b)the leasing of any intermodal equipment.\n[S 338/2021 wef 24/02/2015]"}},{"id":"SG-H2188-A6","no":6,"noLabel":{"en":"6."},"heading":{"en":"Exemption in relation to applicable finance lease"},"text":{"en":"6.—(1) Subject to sub-paragraphs (2) to (5) and the conditions imposed by the Minister under section 13(4) of the Act, any qualifying payment that an approved container investment enterprise is liable to make between 24 February 2015 and 11 December 2018 (both dates inclusive) to a specified person under an applicable finance lease, is exempt from tax.\n(2) Where any container that is not within the meaning of “container” in section 43P(7) of the Act is leased under the applicable finance lease, the exemption applies only to the amount of the qualifying payment derived by the formula where —\n(a)A is that part of the principal of the applicable finance lease that is attributable to —\n(i)the leasing of those containers that are each within the meaning of “container” in section 43P(7) of the Act;\n[S 307/2024 wef 31/12/2021]\n(ii)the leasing of equipment installed or to be installed within or on those containers mentioned in sub-paragraph (i); and\n(iii)the leasing of intermodal equipment under the applicable finance lease;\n(b)B is the principal of the applicable finance lease; and\n(c)C is the qualifying payment.\n[S 307/2024 wef 31/12/2021]\n(3) The exemption under sub-paragraph (1) does not apply to any payment or part of a payment under a finance lease entered into before 24 February 2015, being a payment or part of a payment that is exempt from tax under any other exemption granted under the Act or any subsidiary legislation made under the Act.\n(4) The exemption under sub-paragraph (1) only applies to a qualifying payment liable to be made —\n(a)at any time on or after the date the enterprise makes a declaration, in relation to the applicable finance lease, to the Authority in the form specified by the Authority for the purposes of this sub-paragraph; or\n(b)if the declaration is made on or before the 15th day of a month, at any time on or after the first day of the previous month.\n(5) The exemption under sub-paragraph (1) does not apply to any payment liable to be made —\n(a)after the day that the applicable finance lease ceases to be treated as a sale pursuant to regulations made under section 10C of the Act;\n[S 307/2024 wef 31/12/2021]\n(b)after the day that any original container (being a container that is within the meaning of “container” in section 43P(7) of the Act) is disposed of or is lost at sea, unless the terms of the agreement for the applicable finance lease —\n(i)require that all original containers disposed of and lost at sea be replaced in the event that the value of such containers exceeds a sum stipulated in the applicable finance lease; or\n(ii)require the repayment of that part of the principal of the applicable finance lease attributable to the cost of acquiring all original containers disposed of and lost at sea in the event that the value of such containers exceeds a sum stipulated in the applicable finance lease; or\n[S 307/2024 wef 31/12/2021]\n(c)on or after the day that the approval of the approved container investment enterprise as such is revoked or withdrawn.\n(6) Where —\n(a)sub-paragraph (1) has operated to exempt from tax any qualifying payment liable to be made under an applicable finance lease mentioned in that sub-paragraph; and\n(b)the term of the approval of the approved container investment enterprise as such subsequently expires,\nthen any qualifying payment liable to be made under that applicable finance lease by the enterprise on or after the date of the expiry to a person mentioned in that sub-paragraph, is also exempt from tax.\n(7) The exemption under sub-paragraph (6) is subject to the conditions mentioned in sub-paragraph (1) and to sub-paragraphs (2), (3) and (5), and for this purpose those sub-paragraphs apply as if a reference to an approved container investment enterprise were a reference to a container investment enterprise.\n[S 338/2021 wef 24/02/2015]"}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Interest and Other Payments on Economic and Technological Development Loans and Finance Leases) (No. 4) Notification 2016","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
