  FT["SG-H2242"] = {"id":"SG-H2242","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S337-2011?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（经济发展与技术开发付款豁免）（第 2 号）公告 2011","en":"Income Tax (Exemption of Payments for Economic and Technological Development) (No. 2) Notification 2011","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S337-2011","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2242-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Notification may be cited as the Income Tax (Exemption of Payments for Economic and Technological Development) (No. 2) Notification 2011."}},{"id":"SG-H2242-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2. There shall be exempt from tax the royalties payable by Singapore Precision Industries Pte Ltd to the International Olympic Committee on or before 30th July 2011 for the —\n(a)rights granted by the International Olympic Committee under the International Distribution Agreement dated 5th August 2010; and\n(b)rights granted under the Merchandise License Agreement dated 23rd June 2010,\nin respect of the 1st Summer Youth Olympic Games held in Singapore from 14th August 2010 to 26th August 2010."}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Payments for Economic and Technological Development) (No. 2) Notification 2011","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2243"] = {"id":"SG-H2243","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S11-2011?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（经济发展与技术开发付款豁免）公告 2011","en":"Income Tax (Exemption of Payments for Economic and Technological Development) Notification 2011","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S11-2011","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2243-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Notification may be cited as the Income Tax (Exemption of Payments for Economic and Technological Development) Notification 2011."}},{"id":"SG-H2243-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2. There shall be exempt from tax all sums payable by the following companies to the International Olympic Committee for the rights granted by the International Olympic Committee under the respective Memoranda of Understanding between the companies and that Committee in respect of the 1st Summer Youth Olympic Games 2010 held in Singapore from 14th August 2010 to 26th August 2010:\n(a)Singapore Telecommunications Limited under the Memorandum of Understanding dated 18th November 2009;\n(b)MediaCorp Pte. Ltd. under the Memorandum of Understanding dated 30th November 2009; and\n(c)StarHub Cable Vision Ltd. under the Memorandum of Understanding dated 30th November 2009."}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Payments for Economic and Technological Development) Notification 2011","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2244"] = {"id":"SG-H2244","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S223-2009?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"所得税（合格家族投资控股公司相关收入豁免）条例 2009","en":"Income Tax (Exemption of Relevant Income of Eligible Family-owned Investment Holding Company) Regulations 2009","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S223-2009","completenessNote":"全文，共 5 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2244-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Regulations may be cited as the Income Tax (Exemption of Relevant Income of Eligible Family-owned Investment Holding Company) Regulations 2009 and shall be deemed to have come into operation on 1st April 2008."}},{"id":"SG-H2244-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definitions"},"text":{"en":"2.—(1) In these Regulations —\n“connected persons”, in relation to any individual, means —\n(a)his spouse;\n(b)his lineal descendants and their spouses;\n(c)his parents, including step-parents;\n(d)his grandparents;\n(e)his parents-in-law, including step-parents-in-law;\n(f)his brother, step-brother, sister, step-sister and their spouses;\n(g)his spouse’s grandparents;\n(h)his spouse’s brother, step-brother, sister, step-sister and their spouses and children;\n(i)his parent’s brother, step-brother, sister, step-sister and their spouses;\n(j)children of the brother, step-brother, sister or step-sister of his parents, both present and future, including step-children, and their spouses; and\n(k)children of his brother, step-brother, sister or step-sister, both present and future, including step-children, and their spouses;\n“financial institution” means an institution licensed or approved by the Monetary Authority of Singapore, or exempted from such licensing or approval, under any written law administered by the Monetary Authority of Singapore;\n“Monetary Authority of Singapore” means the Monetary Authority of Singapore established under section 3 of the Monetary Authority of Singapore Act (Cap. 186);\n“nominee company” means a company formed by a bank or other fiduciary organisation to hold and administer securities or other assets as a custodian (being the registered owner) on behalf of another person (who is the beneficial owner) under a custodial agreement;\n“related party” has the same meaning as in section 13(16) of the Act.\n(2) In the definition of “connected persons” in paragraph (1) —\n(a)relationships that may be established by blood may also be established by adoption in accordance with any written law relating to the adoption of children;\n(b)“lineal descendants” of an individual means his children, the children of his children, the children of those children and so on; and\n(c)“children” in the definition of “lineal descendants” in sub-paragraph (b) includes step-children."}},{"id":"SG-H2244-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Conditions for exemption"},"text":{"en":"3.—(1) The prescribed conditions for the purpose of the definition of “eligible family-owned investment holding company” in section 13W of the Act, which shall be satisfied throughout the basis period for the year of assessment in question, are as follows:\n(a)subject to sub-paragraph (b), all the issued shares of the company are beneficially owned by one or more individuals;\n(b)where all the issued shares are beneficially owned by more than one individual, all the individuals are connected persons by reference to any one of them;\n(c)a financial institution in Singapore is engaged to —\n(i)administer the company;\n(ii)manage the financial assets of the company; or\n(iii)provide advice on the management of the financial assets of the company;\n(d)the company’s transactions with related parties are carried out on an arm’s length basis; and\n(e)unless made under an arm’s length transaction —\n(i)no assets are transferred directly or indirectly to the company by any person who carried on a business in Singapore and whose income in relation to those assets was not or would not be (as the case may be), exempted from tax; and\n(ii)no shares in the company are transferred where such transfer would result in sub-paragraphs (a) and (b) being satisfied if, at any time prior to the transfer, the company was carrying on a business in Singapore which generated income that was not or would not be (as the case may be) exempted from tax.\n(2) For the purposes of paragraph (1)(a) and (b), where —\n(a)an individual beneficially owns (including by virtue of one or more applications of this paragraph) equity interests of a nominee company or another eligible family-owned investment holding company (referred to in this paragraph as a first level entity); and\n(b)the first level entity beneficially owns equity interests of another nominee company or another eligible family-owned investment holding company (referred to in this paragraph as a second level entity),\nthen the individual is taken to beneficially own equity interests of the second level entity."}},{"id":"SG-H2244-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Deduction of certain losses not allowed"},"text":{"en":"4. Any expenses in excess of the relevant income of an eligible family-owned investment holding company shall not be set-off against or be allowable as a loss against any income of the company that is chargeable to tax and shall be disregarded."}},{"id":"SG-H2244-A5","no":5,"noLabel":{"en":"5."},"heading":{"en":"Annual declaration"},"text":{"en":"5.—(1) An eligible family-owned investment holding company shall submit an annual declaration in accordance with paragraph (2) that the conditions for exemption under section 13W of the Act are satisfied.\n(2) The declaration shall be made to the Comptroller and the Monetary Authority of Singapore in respect of each basis period relating to any year of assessment and shall be made in such form and within such time as the Comptroller or the Monetary Authority of Singapore may specify."}}],"pack":"sg-p28","titleTranslation":{"engine":"manual-llm","reviewed":false,"source":"Income Tax (Exemption of Relevant Income of Eligible Family-owned Investment Holding Company) Regulations 2009","note":"人工逐条翻译（模型产出，未经人工复核）；公司名、地名、机构名保留原文。"}};
  FT["SG-H2245"] = {"id":"SG-H2245","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S530-2003?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"所得税（经济与技术发展特许权使用费及其他付款豁免）（第 2 号）公告 2003","en":"Income Tax (Exemption of Royalties and Other Payments for Economic and Technological Development) (No. 2) Notification 2003","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S530-2003","completenessNote":"全文，共 3 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2245-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Notification may be cited as the Income Tax (Exemption of Royalties and Other Payments for Economic and Technological Development) (No. 2) Notification 2003."}},{"id":"SG-H2245-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definitions"},"text":{"en":"2. In this Notification —\n“digitised goods” means text, images or sounds that are transferred through any handphone, fixed-line phone, cable network, satellite, the Internet, or other form of electronic transmission, but does not include software;\n“end-user” means a person who acquires the right to use any information or digitised goods but does not acquire the right to exploit the copyright of the information or digitised goods in the course of a business or holds himself out as having done so;\n“information” means —\n(a)information comprised in any newspaper or magazine article or report, including financial and business data (such as foreign exchange, stock and property data) and other proprietary data; and\n(b)information obtained solely for research purposes."}},{"id":"SG-H2245-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Exemption"},"text":{"en":"3. There shall be exempt from tax any income referred to in section 12(7) of the Act of a non-resident person accruing in or derived from Singapore during the period from 28th February 2003 to 27th February 2013 (both dates inclusive) that is a payment —\n(a)made to the non-resident person by an end-user for —\n(i)information; or\n(ii)digitised goods;\n(b)not derived from any trade or business carried on or exercised by the non-resident person in Singapore; and\n(c)not effectively connected with any permanent establishment in Singapore."}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Royalties and Other Payments for Economic and Technological Development) (No. 2) Notification 2003","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2246"] = {"id":"SG-H2246","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-N12?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（经济发展与技术开发特许权使用费及其他付款豁免）公告","en":"Income Tax (Exemption of Royalties and Other Payments for Economic and Technological Development) Notification","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-N12","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2246-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Notification may be cited as the Income Tax (Exemption of Royalties and Other Payments for Economic and Technological Development) Notification."}},{"id":"SG-H2246-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) There shall be exempt from tax any income of a person who is neither a resident of nor a permanent establishment in Singapore, being a payment made to that person —\n(a)at any time during the period from 11th July 1997 to 10th July 2012 (both dates inclusive) for the use of or the right to use any facility or equipment in a space satellite;\n(b)for the use of or the right to use any facility or equipment in a space satellite where the liability to make that payment arises at any time during the period from 11th July 1997 to 27th February 2013 (both dates inclusive); or\n(c)for the use of or the right to use any facility or equipment in a space satellite at any time during the period from 11th July 1997 to 27th February 2013 (both dates inclusive).\n[S 516/2009 wef 27/10/2009]\n(1A) There shall be exempt from tax any income of a person who is neither a resident of nor a permanent establishment in Singapore, being a payment made to that person for the use of or the right to use any facility or equipment in a space satellite where the liability to make that payment arises after 27th February 2013 —\n(a)under a contract (for such use or right to use) which takes effect at any time during the period from 11th July 1997 to 27th February 2013 (both dates inclusive); or\n(b)under a contract (for such use or right to use) which is extended or renewed, where the extension or renewal takes effect at any time during the period from 11th July 1997 to 27th February 2013 (both dates inclusive).\n[S 516/2009 wef 27/10/2009]\n(2) In this paragraph, “space satellite” means an apparatus placed in orbit relative to the earth for any economic, scientific or technological purpose.\n[S 516/2009 wef 27/10/2009]"}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Royalties and Other Payments for Economic and Technological Development) Notification","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2247"] = {"id":"SG-H2247","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-N9?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（经济发展与技术开发特许权使用费及其他付款豁免）公告","en":"Income Tax (Exemption of Royalties and Other Payments for Economic and Technological Development) Notification","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-N9","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2247-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Notification may be cited as the Income Tax (Exemption of Royalties and Other Payments for Economic and Technological Development) Notification."}},{"id":"SG-H2247-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2. The withholding tax on the royalties payable by the Public Utilities Board to Power Technologies Inc, USA, under the Contract No. PUB PE 39030-000 shall be at a reduced rate of 10%."}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Royalties and Other Payments for Economic and Technological Development) Notification","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2248"] = {"id":"SG-H2248","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S97-2001?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"所得税（经济发展与技术开发特许权使用费及其他付款豁免）公告 2001","en":"Income Tax (Exemption of Royalties and Other Payments for Economic and Technological Development) Notification 2001","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S97-2001","completenessNote":"全文，共 6 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2248-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Notification may be cited as the Income Tax (Exemption of Royalties and Other Payments for Economic and Technological Development) Notification 2001."}},{"id":"SG-H2248-A1.001","no":1.001,"noLabel":{"en":"1A."},"heading":{"en":"Definitions"},"text":{"en":"1A. For the purposes of this Notification —\n“downloadable software” means software downloaded by an end-user from the Internet or a network for a fee and where the end-user only receives the right to use the software but is not permitted to reverse engineer, decompile, or disassemble the software;\n“end-user” means an user who acquires the right to run the software on a single computer or computer network but does not have the right to exploit the copyright to the software;\n“maintenance and support services” includes software technical support via telephone or on-line services, delivery of updates or upgrades, remote correction of defects, or installation services provided in connection with a site licence;\n“site licence” means a software licence where —\n(a)the licensee only receives the right to use the software but is not permitted to reverse engineer, decompile, or disassemble the software, or exploit the copyright to the software; and\n(b)the licensee is permitted to install the software on any number of computers or servers for operation within its own business, location or facility,\nand includes any maintenance and support services that are not priced separately and are incidental to the grant of the software licence;\n“software bundled with computer hardware” means software that has been pre-installed in the computer hardware and is distributed under the following conditions:\n(a)the software and computer hardware are sold together as a single product without being priced separately;\n(b)the buyer only receives the right to use the software on the computer hardware; and\n(c)the buyer is not permitted to reverse engineer, decompile, or disassemble the software, or resell the software on its own.\n[S 267/2001 wef 09/05/2001]"}},{"id":"SG-H2248-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption for shrink-wrap software"},"text":{"en":"2. Subject to paragraph 3, there shall be exempt from tax any payment made for shrink-wrap software in the nature of income referred to in section 12(7) of the Act accruing in or derived from Singapore during the period from 1 January 2001 to 27 February 2013 (both dates inclusive) by any non-resident person.\n[S 136/2015 wef 28/02/2013]"}},{"id":"SG-H2248-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Terms and conditions of exemption under paragraph 2"},"text":{"en":"3. The exemption under paragraph 2 shall apply only if the payment for shrink-wrap software —\n(a)is for software distributed only in the form of compact discs or floppy diskettes in wrapped boxes accompanied by shrink-wrapped licences granting the purchaser the right to use the software under the following conditions:\n(i)the purchaser only receives the right to use the software but is not permitted to modify it in any way;\n(ii)the purchaser is not licensed to reverse engineer, de-compile, or disassemble the computer program; and\n(iii)the purchaser may resell his copy of the software as long as any other copies he has made are destroyed and the same terms and conditions of the licence are imposed on the subsequent purchaser; and\n(b)is made to a non-resident person and the payment —\n(i)is not derived by that person from any trade or business carried on or exercised by him in Singapore; and\n(ii)is not effectively connected with any permanent establishment in Singapore.\n[S 267/2001 wef 09/05/2001]"}},{"id":"SG-H2248-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Exemption for site licence, etc."},"text":{"en":"4. Subject to paragraph 5, there shall be exempt from tax any payment made for —\n(a)a site licence;\n(b)downloadable software; or\n(c)software bundled with computer hardware,\nin the nature of income referred to in section 12(7) of the Act accruing in or derived from Singapore during the period from 23 February 2001 to 27 February 2013 (both dates inclusive) by any non-resident person.\n[S 267/2001 wef 09/05/2001]\n[S 136/2015 wef 28/02/2013]"}},{"id":"SG-H2248-A5","no":5,"noLabel":{"en":"5."},"heading":{"en":"Terms and conditions of exemption under paragraph 4"},"text":{"en":"5. The exemption under paragraph 4 shall apply only if the payment referred to in that paragraph is made to a non-resident person and the payment —\n(a)is not derived by that person from any trade or business carried on or exercised by him in Singapore; and\n(b)is not effectively connected with any permanent establishment in Singapore.\n[S 267/2001 wef 09/05/2001]"}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Royalties and Other Payments for Economic and Technological Development) Notification 2001","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2249"] = {"id":"SG-H2249","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S529-2003?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"所得税（经济与技术发展特许权使用费及其他付款豁免）公告 2003","en":"Income Tax (Exemption of Royalties and Other Payments for Economic and Technological Development) Notification 2003","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S529-2003","completenessNote":"全文，共 3 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2249-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Notification may be cited as the Income Tax (Exemption of Royalties and Other Payments for Economic and Technological Development) Notification 2003."}},{"id":"SG-H2249-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definitions"},"text":{"en":"2. In this Notification\n“Indefeasible Right of Use” or “IRU” means an indefeasible right to use an international telecommunications submarine cable system;\n“international telecommunications submarine cable system” means an international submarine cable that is laid in the sea and includes its cable landing station and any other equipment ancillary to the submarine cable system."}},{"id":"SG-H2249-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Exemption"},"text":{"en":"3.—(1) Subject to sub-paragraph (2), there shall be exempt from tax any income of a person not resident in Singapore (referred to in this paragraph as a non-resident person), being a payment made to the non-resident person for the use of or right to use any international telecommunication submarine cable capacity (including any payment for an IRU), and accruing in or derived from Singapore —\n(a)during the period from 28th February 2003 to 27th February 2013 (both dates inclusive); or\n(b)after 27th February 2013 —\n(i)under a contract for such use or right to use which takes effect at any time during the period from 28th February 2003 to 27th February 2013 (both dates inclusive); or\n(ii)under a contract for such use or right to use which is extended or renewed, where the extension or renewal takes effect at any time during the period from 28th February 2003 to 27th February 2013 (both dates inclusive).\n(1A) Subject to sub‑paragraph (2), there shall be exempt from tax any income of a non-resident person, being a payment made to the non‑resident person for an IRU, and accruing in or derived from Singapore —\n(a)during the period from 28th February 2013 to 27th February 2018 (both dates inclusive); or\n(b)after 27th February 2018 —\n(i)under a contract for the IRU which takes effect at any time during the period from 28th February 2013 to 27th February 2018 (both dates inclusive); or\n(ii)under a contract for the IRU which is extended or renewed, where the extension or renewal takes effect at any time during the period from 28th February 2013 to 27th February 2018 (both dates inclusive).\n[S 678/2013 wef 28/02/2013]\n(1B) Subject to sub‑paragraph (2), the income of a non‑resident person that comprises a payment made to the non‑resident person for an IRU, and accruing in or derived from Singapore —\n(a)during the period from 28 February 2018 to 31 December 2028 (both dates inclusive); or\n[S 820/2023 wef 01/01/2024]\n(b)after 31 December 2028 —\n(i)under a contract for the IRU which takes effect at any time during the period from 28 February 2018 to 31 December 2028 (both dates inclusive); or\n(ii)under a contract for the IRU which is extended or renewed, where the extension or renewal takes effect at any time during the period from 28 February 2018 to 31 December 2028 (both dates inclusive),\n[S 820/2023 wef 01/01/2024]\nis exempt from tax.\n[S 648/2017 wef 28/02/2018]\n(2) The exemption under sub‑paragraphs (1), (1A) and (1B) shall not apply to any income of the non-resident person which is —\n(a)derived from any trade or business carried on in Singapore by the non-resident person; or\n(b)effectively connected with any permanent establishment in Singapore of the non-resident person.\n[S 678/2013 wef 28/02/2013]\n[S 109/2008 wef 29/02/2008]\n[S 648/2017 wef 28/02/2018]"}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Royalties and Other Payments for Economic and Technological Development) Notification 2003","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2250"] = {"id":"SG-H2250","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S116-2016?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（经济发展与技术开发特许权使用费及其他付款豁免）公告 2016","en":"Income Tax (Exemption of Royalties and Other Payments for Economic and Technological Development) Notification 2016","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S116-2016","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2250-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Exemption of Royalties and Other Payments for Economic and Technological Development) Notification 2016 and is deemed to have come into operation on 1 July 2014."}},{"id":"SG-H2250-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) The royalties payable by ESS (a partnership formed under the laws of the State of Delaware, USA), during the period specified in sub‑paragraph (2) under an agreement specified in the letter dated 16 September 2015 addressed to ESS and Fox International Channels Singapore Pte. Ltd. (called in this paragraph the 16 September 2015 letter), are exempt from tax.\n(2) The period for the purpose of sub‑paragraph (1) commences on 1 July 2014 and ends on the earlier of the following dates:\n(a)31 December 2015;\n(b)the date of termination of the agreement.\n(3) The exemption in sub‑paragraph (1) is subject to the terms and conditions specified in the 16 September 2015 letter."}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Royalties and Other Payments for Economic and Technological Development) Notification 2016","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2251"] = {"id":"SG-H2251","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S537-2019?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（工作福利开埠两百周年红利豁免）公告 2019","en":"Income Tax (Exemption of Workfare Bicentennial Bonus) Notification 2019","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S537-2019","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2251-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Exemption of Workfare Bicentennial Bonus) Notification 2019 and comes into operation on 1 August 2019."}},{"id":"SG-H2251-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2. Any cash payment to an individual, made by the Government under the Workfare Bicentennial Bonus scheme, is exempt from tax."}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Workfare Bicentennial Bonus) Notification 2019","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2252"] = {"id":"SG-H2252","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S1001-2020?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（就业奖励特别补助豁免——第 13(1)(zp) 条）公告 2020","en":"Income Tax (Exemption of Workfare Special Payment — Section 13(1)(zp)) Notification 2020","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S1001-2020","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2252-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Exemption of Workfare Special Payment — Section 13(1)(zp)) Notification 2020 and comes into operation on 9 December 2020."}},{"id":"SG-H2252-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2. Any cash payment to an individual, made by the Government under the scheme known as the Workfare Special Payment that is part of the Budget Statements of the Government dated 18 February 2020 and 26 March 2020 and the ministerial statement of the Minister dated 17 August 2020, is exempt from tax."}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Workfare Special Payment — Section 13(1)(zp)) Notification 2020","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2253"] = {"id":"SG-H2253","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S995-2020?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"所得税（第 13ZA(3) 条下的豁免）规则 2020","en":"Income Tax (Exemption under Section 13ZA(3)) Rules 2020","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S995-2020","completenessNote":"全文，共 4 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2253-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Rules are the Income Tax (Exemption under Section 13ZA(3)) Rules 2020 and come into operation on 7 December 2020."}},{"id":"SG-H2253-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definitions"},"text":{"en":"2. In these Rules, “COVID‑19” and “COVID‑19 event” have the meanings given by section 13ZA(6) of the Act."}},{"id":"SG-H2253-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Exemption for provision of place of residence or allowance for accommodation"},"text":{"en":"3.—(1) The conditions for exemption from tax for the matters mentioned in section 13ZA(3)(a) of the Act are —\n(a)the provision of the place of residence in Singapore, or the allowance for accommodation in Singapore, to the individual is for either of the following purposes only:\n(i)to enable the individual (being one who ordinarily resides outside Singapore) to reside in Singapore to ensure the continuity of the employer’s trade or business at any time during the period from 1 February 2020 to 31 December 2020 (both dates inclusive);\n(ii)because there is a high risk of the individual contracting COVID‑19 due to the nature of the individual’s employment or due to the fact that the individual is required to travel out of Singapore for his or her employment at any time during the period from 1 February 2020 to 31 December 2020 (both dates inclusive) — to reduce, as a result of the risk, the risk of the individual in turn infecting others with COVID‑19; and\n(b)before 1 February 2020, the individual’s employer did not provide to the individual or an employee with the same job scope as the individual a place of residence in Singapore, or an allowance for accommodation in Singapore.\nExample\nAn individual has a high risk of contracting COVID‑19 due to the nature of the individual’s employment if he or she is required to provide care to individuals who have contracted or are suspected to have contracted COVID‑19.\n(2) The prescribed amount mentioned in section 13ZA(3)(a) of the Act is $75."}},{"id":"SG-H2253-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Exemption for provision of basic necessities or allowance for basic necessities"},"text":{"en":"4.—(1) The conditions for exemption from tax for the matters mentioned in section 13ZA(3)(b) of the Act are —\n(a)the provision of the basic necessities, or the allowance for basic necessities, to the individual is for any of the following purposes only:\n(i)to enable the individual (being one who ordinarily resides outside Singapore) to reside in Singapore to ensure the continuity of the employer’s trade or business at any time during the period from 1 February 2020 to 31 December 2020 (both dates inclusive);\n(ii)because there is a high risk of the individual contracting COVID‑19 due to the nature of the individual’s employment or due to the fact that the individual is required to travel out of Singapore for his or her employment at any time during the period from 1 February 2020 to 31 December 2020 (both dates inclusive) — to reduce that risk, or the resulting risk of the individual infecting others with COVID‑19;\n(iii)because a requirement of the individual’s employment that is imposed at any time during the period from 1 February 2020 to 31 December 2020 (both dates inclusive) in order to ensure business continuity in light of a COVID‑19 event exposes the individual to an elevated risk of contracting COVID‑19 — to reduce that risk; and\nExample\nAn individual has an elevated risk of contracting COVID‑19 because of a requirement of his or her employment, if the individual is required to report to a workplace that is not his or her place of residence during the period from 7 April 2020 to 1 June 2020 (being the period known as the Circuit Breaker).\n(b)before 1 February 2020, the individual’s employer did not provide to the individual or an employee with the same job scope as the individual basic necessities, or an allowance for basic necessities, for consumption or use in Singapore, except to enable the individual to carry out his or her duties outside of his or her hours of duties or in exceptional circumstances.\n(2) The prescribed amount mentioned in section 13ZA(3)(b) of the Act is $50."}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption under Section 13ZA(3)) Rules 2020","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2254"] = {"id":"SG-H2254","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S248-2022?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"所得税（第 10J(5) 与 32A(4) 条下通知的豁免）规则 2022","en":"Income Tax (Exemptions from Notification under Sections 10J(5) and 32A(4)) Rules 2022","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S248-2022","completenessNote":"全文，共 3 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2254-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Rules are the Income Tax (Exemptions from Notification under Sections 10J(5) and 32A(4)) Rules 2022 and are deemed to have come into operation on 16 November 2021."}},{"id":"SG-H2254-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption of individual from sections 10J(5) and 32A(4) of Act"},"text":{"en":"2. A person who is an individual is exempt from sections 10J(5) and 32A(4) of the Act."}},{"id":"SG-H2254-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Section 10J(5) of Act does not apply to certain donations"},"text":{"en":"3. Section 10J(5) of the Act does not apply in a case where a person appropriates by way of a donation any trading stock that is perishable."}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemptions from Notification under Sections 10J(5) and 32A(4)) Rules 2022","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2255"] = {"id":"SG-H2255","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S411-2017?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"所得税（应课税收入估算申报）规则 2017","en":"Income Tax (Filing of Estimates of Chargeable Income) Rules 2017","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S411-2017","completenessNote":"全文，共 7 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2255-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1.—(1) These Rules are the Income Tax (Filing of Estimates of Chargeable Income) Rules 2017.\n(2) Rules 2, 4 and 5 are deemed to have come into operation on 29 December 2016.\n(3) Rules 3 and 6 come into operation on 21 July 2017."}},{"id":"SG-H2255-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definition"},"text":{"en":"2. In these Rules, the revenue of a company or a partnership in a year of assessment is the gross amount of its income derived from its principal activities in the accounting period relating to that year of assessment."}},{"id":"SG-H2255-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Furnishing of estimate of chargeable income using electronic service"},"text":{"en":"3. Every company belonging to the class of companies specified in the first column of the following table must furnish the estimate of the company’s chargeable income using the electronic service in the year or years of assessment specified opposite in the table:\nFirst column\nSecond column\n1.Companies with revenue of more than $10 million in year of assessment 2017\n2018\n2.Companies with revenue of more than $1 million in year of assessment 2018\n2019\n3.All companies\n2020 and subsequent years of assessment."}},{"id":"SG-H2255-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Exemption for company from furnishing estimate of chargeable income"},"text":{"en":"4. A company is exempt from section 63(1) of the Act in respect of a year of assessment if —\n(a)its revenue in that year of assessment —\n(i)where the accounting period to which the year of assessment relates ends before 1 July 2017 — is not more than $1 million; or\n(ii)where the accounting period to which the year of assessment relates ends on or after 1 July 2017 — is not more than $5 million; and\n(b)the estimate of its chargeable income for that year of assessment is nil."}},{"id":"SG-H2255-A4.001","no":4.001,"noLabel":{"en":"4A."},"heading":{"en":"Exemption for insurer from furnishing estimate of chargeable income"},"text":{"en":"4A. An insurer is exempt from section 63(1AAA) of the Act in respect of a year of assessment if —\n(a)its revenue in that year of assessment is not more than $5 million; and\n(b)the estimate of its chargeable income for that year of assessment is nil.\n[S 6/2023 wef 11/01/2023]"}},{"id":"SG-H2255-A5","no":5,"noLabel":{"en":"5."},"heading":{"en":"Exemption for person from furnishing estimate of chargeable income in relation to partnership"},"text":{"en":"5. A person is exempt from furnishing an estimate of income and other information in relation to a partnership for a year of assessment under section 71(3) of the Act, if —\n(a)the accounting period relating to that year of assessment ends in the month of October, November or December; or\n(b)the revenue of the partnership in the year of assessment immediately before the firstmentioned year of assessment is less than $500,000."}},{"id":"SG-H2255-A6","no":6,"noLabel":{"en":"6."},"heading":{"en":"Revocation"},"text":{"en":"6. The Income Tax (Electronic Filing of Estimates of Chargeable Income) Rules 2017 (G.N. No. S 135/2017) are revoked."}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Filing of Estimates of Chargeable Income) Rules 2017","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2256"] = {"id":"SG-H2256","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S790-2020?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"所得税（集装箱融资租赁——第 13(4) 条豁免）公告 2020","en":"Income Tax (Finance Lease of Container — Section 13(4) Exemption) Notification 2020","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S790-2020","completenessNote":"全文，共 4 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2256-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Finance Lease of Container — Section 13(4) Exemption) Notification 2020 and is deemed to have come into operation on 12 December 2018."}},{"id":"SG-H2256-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definitions"},"text":{"en":"2. In this Notification —\n“approved container investment enterprise” —\n(a)means an approved container investment enterprise mentioned in section 43P of the Act; and\n[S 308/2024 wef 31/12/2021]\n(b)includes a partnership approved by the Minister (or an authorised body) under section 43P of the Act as applied by section 36 of the Act;\n[S 308/2024 wef 31/12/2021]\n[S 308/2024 wef 12/04/2024]\n“approved international shipping enterprise” means an approved international shipping enterprise mentioned in section 13E of the Act;\n[S 308/2024 wef 31/12/2021]\n“container”, “container investment enterprise” and “intermodal equipment” have the meanings given by section 43P(7) of the Act;\n[S 308/2024 wef 31/12/2021]\n“finance lease”, in relation to any container or intermodal equipment, means a lease of the container or intermodal equipment (including any arrangement or agreement made in connection with the lease) that has the effect of transferring substantially the obsolescence, risks or rewards incidental to ownership of the container or intermodal equipment to the lessee;\n“international shipping enterprise” has the meaning given by section 13E(6) of the Act;\n[S 308/2024 wef 31/12/2021]\n“shipping enterprise” means any company that owns or operates one or more Singapore ships;\n“Singapore ship” —\n(a)means a ship in respect of which a certificate of registry has been issued under the Merchant Shipping Act 1995 and whose registry is not closed or deemed to be closed or suspended; and\n[S 308/2024 wef 31/12/2021]\n(b)includes a ship that is provisionally registered under the Merchant Shipping Act 1995.\n[S 308/2024 wef 31/12/2021]"}},{"id":"SG-H2256-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Exemption for payment under finance lease of container by shipping enterprise"},"text":{"en":"3.—(1) Subject to this paragraph, any payment that a shipping enterprise is liable to make on or after 12 December 2018 to a person resident outside Singapore (called in this Notification a non‑resident person) under a finance lease entered into on or before 31 December 2028 of at least one container for the carriage of goods by sea and intermodal equipment (if it is included in the finance lease of the container or containers), is exempt from tax.\n[S 158/2022 wef 04/03/2022]\n(2) Sub‑paragraph (1) does not apply to —\n(a)any payment liable to be made under the finance lease that is derived from any operation carried on by the non‑resident person through the person’s permanent establishment in Singapore;\n(b)any payment liable to be made under the finance lease after the day that the container or (where more than one container is the subject of the finance lease) one or more of the containers is or are disposed of or lost at sea (called in this sub‑paragraph disposed container or containers), unless the terms of the finance lease —\n(i)require that the disposed container or containers (as the case may be) be replaced, if the value or the total value of the disposed container or containers exceeds a sum stipulated in the finance lease; or\n(ii)require the repayment of that part of the finance lease attributable to the cost of acquiring the disposed container or containers (as the case may be), if the value or the total value of the disposed container or containers exceeds a sum stipulated in the finance lease; or\n(c)any payment liable to be made under the finance lease on or after the date that the shipping enterprise ceases to own or operate any Singapore ship.\n(3) Where the shipping enterprise mentioned in sub‑paragraph (1) owns or operates only one ship, and that ship is provisionally registered under the Merchant Shipping Act 1995, the exemption is subject to the condition that the ship subsequently obtains a certificate of registry under that Act.\n[S 308/2024 wef 31/12/2021]"}},{"id":"SG-H2256-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Exemption for payment under finance lease of container by approved international shipping enterprise or approved container investment enterprise"},"text":{"en":"4.—(1) Subject to this paragraph, any payment that an approved international shipping enterprise or approved container investment enterprise is liable to make to a non‑resident person on or after 12 December 2018 under any finance lease entered into on or before 31 December 2028 of at least one container for the carriage of goods by sea and intermodal equipment (if it is included in the finance lease of the container or containers), is exempt from tax.\n[S 158/2022 wef 04/03/2022]\n(2) Sub‑paragraph (1) does not apply to —\n(a)any payment liable to be made under the finance lease that is derived from any operation carried on by the non‑resident person through the person’s permanent establishment in Singapore;\n(b)any payment liable to be made under the finance lease after the day that the container or (where more than one container is the subject of the finance lease) one or more of the containers is or are disposed of or lost at sea (called in this sub‑paragraph disposed container or containers), unless the terms of the finance lease —\n(i)require that the disposed container or containers (as the case may be) be replaced, if the value or the total value of the disposed container or containers exceeds a sum stipulated in the finance lease; or\n(ii)require the repayment of that part of the finance lease attributable to the cost of acquiring the disposed container or containers (as the case may be), if the value or the total value of the disposed container or containers exceeds a sum stipulated in the finance lease; or\n(c)any payment liable to be made under the finance lease on or after the date that the approval of the approved international shipping enterprise or approved container investment enterprise is revoked or withdrawn.\n(3) Sub‑paragraph (1) continues to apply to an international shipping enterprise or a container investment enterprise the approval of which has expired, but that remains liable to make any payment under the finance lease on or after the date of the expiry of the approval.\n(4) For the purposes of sub‑paragraph (3), a reference in sub‑paragraphs (1) and (2) to an approved international shipping enterprise or approved container investment enterprise is to an international shipping enterprise or a container investment enterprise, as the case may be."}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Finance Lease of Container — Section 13(4) Exemption) Notification 2020","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2257"] = {"id":"SG-H2257","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S789-2020?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"所得税（船舶融资租赁——第 13(4) 条豁免）公告 2020","en":"Income Tax (Finance Lease of Ship — Section 13(4) Exemption) Notification 2020","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S789-2020","completenessNote":"全文，共 4 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2257-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Finance Lease of Ship — Section 13(4) Exemption) Notification 2020 and is deemed to have come into operation on 12 December 2018."}},{"id":"SG-H2257-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definitions"},"text":{"en":"2. In this Notification —\n“approved international shipping enterprise” means an approved international shipping enterprise mentioned in section 13E of the Act;\n[S 309/2024 wef 31/12/2021]\n“approved shipping investment enterprise” —\n(a)means an approved shipping investment enterprise mentioned in section 13P of the Act; and\n[S 309/2024 wef 31/12/2021]\n(b)includes a partnership approved by the Minister (or an authorised body) under section 13P of the Act as applied by section 36 of the Act;\n[S 309/2024 wef 31/12/2021]\n[S 309/2024 wef 12/04/2024]\n“finance lease”, in relation to a ship, means a lease of the ship (including any arrangement or agreement made in connection with the lease) that has the effect of transferring substantially the obsolescence, risks or rewards incidental to ownership of the ship to the lessee;\n“foreign ship” means a sea‑going ship other than a Singapore ship;\n“international shipping enterprise” has the meaning given by section 13E(6) of the Act;\n[S 309/2024 wef 31/12/2021]\n“provisionally registered ship” means a ship that is provisionally registered under the Merchant Shipping Act 1995, but excludes one whose registry is closed, deemed closed or suspended;\n[S 309/2024 wef 31/12/2021]\n“shipping enterprise” means a company that owns or operates one or more Singapore ships;\n“shipping investment enterprise” has the meaning given by section 13P(20) of the Act;\n[S 309/2024 wef 31/12/2021]\n“Singapore ship” —\n(a)means a ship in respect of which a certificate of registry has been issued under the Merchant Shipping Act 1995 and whose registry is not closed or deemed to be closed or suspended; and\n[S 309/2024 wef 31/12/2021]\n(b)includes a provisionally registered ship."}},{"id":"SG-H2257-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Exemption for payment under finance lease of Singapore ship"},"text":{"en":"3.—(1) Subject to this paragraph, any payment that a shipping enterprise is liable to make on or after 12 December 2018 to a person resident outside Singapore (called in this Notification a non‑resident person) under a finance lease of any Singapore ship that is entered into on or before 31 December 2028, is exempt from tax.\n[S 157/2022 wef 04/03/2022]\n(2) Sub‑paragraph (1) does not apply to —\n(a)any payment liable to be made under the finance lease that is derived from any operation carried on by the non‑resident person through the person’s permanent establishment in Singapore; or\n(b)any payment liable to be made under the finance lease on or after the date on which the Singapore ship ceases to be a Singapore ship.\n(3) Where the finance lease mentioned in sub‑paragraph (1) is in relation to a provisionally registered ship, and the shipping enterprise liable to make payment under the finance lease is not an approved international shipping enterprise or approved shipping investment enterprise, the exemption is subject to the condition that the ship subsequently obtains a certificate of registry under the Merchant Shipping Act 1995.\n[S 309/2024 wef 31/12/2021]"}},{"id":"SG-H2257-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Exemption for payment under finance lease of foreign ship"},"text":{"en":"4.—(1) Subject to this paragraph, any payment that an approved international shipping enterprise or approved shipping investment enterprise is liable to make on or after 12 December 2018 to a non‑resident person under a finance lease of any foreign ship that is entered into on or before 31 December 2028, is exempt from tax.\n[S 157/2022 wef 04/03/2022]\n(2) Sub‑paragraph (1) does not apply to —\n(a)any payment liable to be made under the finance lease that is derived from any operation carried on by the non‑resident person through the person’s permanent establishment in Singapore; or\n(b)any payment liable to be made on or after the date that the approval of the approved international shipping enterprise or approved shipping investment enterprise is revoked or withdrawn.\n(3) Sub‑paragraph (1) continues to apply to an international shipping enterprise or a shipping investment enterprise the approval of which has expired, but that remains liable to make any payment under the finance lease on or after the date of expiry of the approval.\n(4) For the purposes of sub‑paragraph (3), a reference in sub‑paragraphs (1) and (2) to an approved international shipping enterprise or approved shipping investment enterprise is to an international shipping enterprise or a shipping investment enterprise, as the case may be."}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Finance Lease of Ship — Section 13(4) Exemption) Notification 2020","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2258"] = {"id":"SG-H2258","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S357-2024?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":9,"structureMode":"ARTICLE","title":{"zh":"所得税（FLCT UK 1 Pte. Ltd. 等——第13条第12款豁免）命令 2024","en":"Income Tax (FLCT UK 1 Pte. Ltd., etc. — Section 13(12) Exemption) Order 2024","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S357-2024","completenessNote":"全文，共 9 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2258-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (FLCT UK 1 Pte. Ltd., etc. — Section 13(12) Exemption) Order 2024."}},{"id":"SG-H2258-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption for FLCT UK 1 Pte. Ltd."},"text":{"en":"2.—(1) Dividend income received in Singapore by FLCT UK 1 Pte. Ltd. (a company incorporated in Singapore) from Connexion Property Co Limited (a company incorporated in Jersey) on or after 18 April 2023, is exempt from tax.\n(2) Trust distribution income received in Singapore by FLCT UK 1 Pte. Ltd. from FLCT UK Trustee 1 Limited (a company incorporated in Jersey) and FLCT UK Trustee 2 Limited (a company incorporated in Jersey) in their capacities as the joint trustees of Connexion Trust (a trust constituted in Jersey) on or after 18 April 2023, is exempt from tax.\n(3) Interest income received in Singapore by FLCT UK 1 Pte. Ltd. from FLCT UK Trustee 1 Limited and FLCT UK Trustee 2 Limited in their capacities as the joint trustees of Connexion Trust on or after 22 February 2022, is exempt from tax.\n(4) The exemptions in sub‑paragraphs (1), (2) and (3) are subject to the terms and conditions specified in the letters from the Ministry of Finance with the dates “19 Apr 2023 (Revised on 3 May 2023)” and “11 Apr 2024” and addressed to EY Corporate Advisors Pte. Ltd."}},{"id":"SG-H2258-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Exemption for FLCT UK 2 Pte. Ltd."},"text":{"en":"3.—(1) Dividend income received in Singapore by FLCT UK 2 Pte. Ltd. (a company incorporated in Singapore) from BVP Property Co Limited (a company incorporated in Jersey) on or after 18 April 2023, is exempt from tax.\n(2) Trust distribution income received in Singapore by FLCT UK 2 Pte. Ltd. from FLCT UK Trustee 1 Limited and FLCT UK Trustee 2 Limited in their capacities as the joint trustees of BVP Trust (a trust constituted in Jersey) on or after 18 April 2023, is exempt from tax.\n(3) Interest income received in Singapore by FLCT UK 2 Pte. Ltd. from FLCT UK Trustee 1 Limited and FLCT UK Trustee 2 Limited in their capacities as the joint trustees of BVP Trust on or after 5 November 2021, is exempt from tax.\n(4) The exemptions in sub‑paragraphs (1), (2) and (3) are subject to the terms and conditions specified in the letters from the Ministry of Finance with the dates “19 Apr 2023 (Revised on 3 May 2023)” and “11 Apr 2024” and addressed to EY Corporate Advisors Pte. Ltd."}},{"id":"SG-H2258-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Exemption for FLCT UK 3 Pte. Ltd."},"text":{"en":"4.—(1) Dividend income and interest income received in Singapore by FLCT UK 3 Pte. Ltd. (a company incorporated in Singapore) from Worcester Property Co Limited (a company incorporated in Jersey) on or after 18 April 2023, are exempt from tax.\n(2) The exemption in sub‑paragraph (1) is subject to the terms and conditions specified in the letters from the Ministry of Finance with the dates “19 Apr 2023 (Revised on 3 May 2023)” and “11 Apr 2024” and addressed to EY Corporate Advisors Pte. Ltd."}},{"id":"SG-H2258-A5","no":5,"noLabel":{"en":"5."},"heading":{"en":"Exemption for FLCT UK 4 Pte. Ltd."},"text":{"en":"5.—(1) Dividend income received in Singapore by FLCT UK 4 Pte. Ltd. (a company incorporated in Singapore) from FLCT Ellesmere Port Property Co Limited (a company incorporated in Jersey) on or after 18 April 2023, is exempt from tax.\n(2) Trust distribution income received in Singapore by FLCT UK 4 Pte. Ltd. from FLCT Ellesmere Trustee 1 Limited (a company incorporated in Jersey) and FLCT Ellesmere Trustee 2 Limited (a company incorporated in Jersey) in their capacities as the joint trustees of FLCT Ellesmere Trust (a trust constituted in Jersey) on or after 18 April 2023, is exempt from tax.\n(3) Interest income received in Singapore by FLCT UK 4 Pte. Ltd. from FLCT Ellesmere Trustee 1 Limited and FLCT Ellesmere Trustee 2 Limited in their capacities as the joint trustees of FLCT Ellesmere Trust on or after 22 February 2022, is exempt from tax.\n(4) The exemptions in sub‑paragraphs (1), (2) and (3) are subject to the terms and conditions specified in the letters from the Ministry of Finance with the dates “19 Apr 2023 (Revised on 3 May 2023)” and “11 Apr 2024” and addressed to EY Corporate Advisors Pte. Ltd."}},{"id":"SG-H2258-A6","no":6,"noLabel":{"en":"6."},"heading":{"en":"Exemption for FLT Europe Pte. Ltd."},"text":{"en":"6.—(1) Dividend income received in Singapore by FLT Europe Pte. Ltd. (a company incorporated in Singapore) from FLT Europe B.V. (a company incorporated in the Netherlands) on or after 18 April 2023, is exempt from tax.\n(2) Interest income received in Singapore by FLT Europe Pte. Ltd. from FLT Europe B.V. on or after 26 November 2021, is exempt from tax.\n(3) The exemptions in sub‑paragraphs (1) and (2) are subject to the terms and conditions specified in the letters from the Ministry of Finance with the dates “19 Apr 2023 (Revised on 3 May 2023)” and “11 Apr 2024” and addressed to EY Corporate Advisors Pte. Ltd."}},{"id":"SG-H2258-A7","no":7,"noLabel":{"en":"7."},"heading":{"en":"Exemption for FLCT UK Pte. Ltd."},"text":{"en":"7.—(1) Interest income received in Singapore by FLCT UK Pte. Ltd. (a company incorporated in Singapore) from Maxis Business Park Limited (a company incorporated in Jersey) on or after 18 April 2023, is exempt from tax.\n(2) The exemption in sub‑paragraph (1) is subject to the terms and conditions specified in the letters from the Ministry of Finance with the dates “19 Apr 2023 (Revised on 3 May 2023)” and “11 Apr 2024” and addressed to EY Corporate Advisors Pte. Ltd."}},{"id":"SG-H2258-A8","no":8,"noLabel":{"en":"8."},"heading":{"en":"Exemption for Frasers Commercial (UK) Sub. 1 Pte Ltd"},"text":{"en":"8.—(1) Interest income received in Singapore by Frasers Commercial (UK) Sub. 1 Pte Ltd (a company incorporated in Singapore) from Farnborough Business Park Limited (a company incorporated in Jersey) on or after 18 April 2023, is exempt from tax.\n(2) The exemption in sub‑paragraph (1) is subject to the terms and conditions specified in the letters from the Ministry of Finance with the dates “19 Apr 2023 (Revised on 3 May 2023)” and “11 Apr 2024” and addressed to EY Corporate Advisors Pte. Ltd."}},{"id":"SG-H2258-A9","no":9,"noLabel":{"en":"9."},"heading":{"en":"Exemption for trustee of Frasers Commercial Trust"},"text":{"en":"9.—(1) Interest income received in Singapore by British & Malayan Trustees Limited (a company incorporated in Singapore) in its capacity as the trustee of Frasers Commercial Trust (a trust constituted in Singapore) from APF Management Pty Limited (a company incorporated in Australia) in its capacity as the trustee of Central Park Landholding Trust (a trust constituted in Australia) on or after 6 March 2023, is exempt from tax.\n(2) The exemption in sub‑paragraph (1) is subject to the terms and conditions specified in the letters from the Ministry of Finance dated 6 March 2023 and 11 April 2024 and addressed to EY Corporate Advisors Pte. Ltd."}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"Income Tax (FLCT UK 1 Pte. Ltd., etc. — Section 13(12) Exemption) Order 2024","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2259"] = {"id":"SG-H2259","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S492-2022?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"所得税（FLCT UK 私人有限公司——第 13(12) 条豁免）命令 2022","en":"Income Tax (FLCT UK Pte. Ltd. — Section 13(12) Exemption) Order 2022","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S492-2022","completenessNote":"全文，共 3 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2259-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (FLCT UK Pte. Ltd. — Section 13(12) Exemption) Order 2022."}},{"id":"SG-H2259-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) The following income received in Singapore by FLCT UK Pte. Ltd. (a company incorporated in Singapore) from Maxis Business Park Limited (a company incorporated in Jersey) on or after 22 June 2021 is exempt from tax:\n(a)dividend income;\n(b)interest income.\n(2) The exemption in sub-paragraph (1) is subject to the conditions specified in the letter of approval dated 22 June 2021 addressed to EY Corporate Advisors Pte. Ltd."}},{"id":"SG-H2259-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Revocation"},"text":{"en":"3. The Income Tax (Frasers Logistics & Commercial Trust UK Pte. Ltd. — Section 13(12) Exemption) Order 2021 (G.N. No. S 754/2021) is revoked."}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (FLCT UK Pte. Ltd. — Section 13(12) Exemption) Order 2022","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2260"] = {"id":"SG-H2260","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S419-2025?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（FLT Europe 私人有限公司依第 13（12）条享有的豁免）命令 2025","en":"Income Tax (FLT Europe Pte. Ltd. — Section 13(12) Exemption) Order 2025","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S419-2025","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2260-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (FLT Europe Pte. Ltd. — Section 13(12) Exemption) Order 2025."}},{"id":"SG-H2260-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Interest income received in Singapore by FLT Europe Pte. Ltd. (a company incorporated in Singapore) on or after 22 April 2025 from FLT Europe B.V. (a company incorporated in the Netherlands), is exempt from tax.\n(2) Sub‑paragraph (1) applies to interest income originating from —\n(a)any rental and property‑related income (including capital gain derived from divestment of property) from any of the properties specified in sub‑paragraph (4); and\n(b)any interest income derived from any temporary deposit with a financial institution in Germany or the Netherlands of such rental and property‑related income.\n(3) The exemption in sub‑paragraph (1) is subject to the conditions specified in the letter from the Inland Revenue Authority of Singapore dated 22 April 2025 that is issued on behalf of the Minister for Finance and addressed to EY Corporate Advisors Pte. Ltd.\n(4) For the purposes of sub‑paragraph (2), the properties are the following:\n(a)the property located at Billbrookdeich 167‑171, 22113 Hamburg, Germany;\n(b)the property located at Werner von Siemens‑Strasse 44, 66793 Saarwellingen, Germany;\n(c)the property located at Thomas Dachser Strasse 3, 66802 Überherrn, Germany;\n(d)the property located at Hans‑Fleißner Straße 46‑48, 63329 Egelsbach, Germany."}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (FLT Europe Pte. Ltd. — Section 13(12) Exemption) Order 2025","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2261"] = {"id":"SG-H2261","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S748-2022?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Frasers 商业投资第 1 号私人有限公司等——第 13(12) 条豁免）命令 2022","en":"Income Tax (Frasers Commercial Investments No. 1 Pte. Ltd., etc. — Section 13(12) Exemption) Order 2022","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S748-2022","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2261-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (Frasers Commercial Investments No. 1 Pte. Ltd., etc. — Section 13(12) Exemption) Order 2022."}},{"id":"SG-H2261-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Trust distribution income from Central Park Landholding Trust (a trust constituted in Australia), received in Singapore by Frasers Commercial Investments No. 1 Pte. Ltd. (a company incorporated in Singapore) on or after 16 September 2020 from APF Management Pty Limited (a company incorporated in Australia) in its capacity as the trustee of Central Park Landholding Trust, is exempt from tax.\n(2) Dividend income received in Singapore by British & Malayan Trustees Limited (a company incorporated in Singapore) in its capacity as the trustee of Frasers Commercial Trust (a trust constituted in Singapore) on or after 16 September 2020 from Frasers Commercial Investments No. 3 Pty Ltd (a company incorporated in the Cayman Islands), is exempt from tax.\n(3) Dividend income received in Singapore by Frasers Commercial Sub No. 2 Pte. Ltd. (a company incorporated in Singapore) on or after 16 September 2020 from Frasers Commercial Investments No. 3 Pty Ltd, is exempt from tax.\n(4) Interest income received in Singapore by British & Malayan Trustees Limited in its capacity as the trustee of Frasers Commercial Trust, on or after 16 September 2020 from Frasers Commercial Investments No. 3 Pty Ltd, is exempt from tax.\n(5) Interest income received in Singapore by Frasers Commercial Sub No. 2 Pte. Ltd. on or after 16 September 2020 from Frasers Commercial Investments No. 3 Pty Ltd, is exempt from tax.\n(6) Dividend income received in Singapore by Frasers Commercial Sub No. 4 Pte. Ltd. (a company incorporated in Singapore) on or after 16 September 2020 from Frasers Commercial Investments No. 4 Pty Ltd (a company incorporated in the Cayman Islands), is exempt from tax.\n(7) Interest income received in Singapore by Frasers Commercial Sub No. 4 Pte. Ltd. on or after 16 September 2020 from Frasers Commercial Investments No. 4 Pty Ltd, is exempt from tax.\n(8) Dividend income received in Singapore by Frasers Commercial (UK) Sub. 1 Pte. Ltd. (a company incorporated in Singapore) on or after 16 September 2020 from Farnborough Business Park Ltd (a company incorporated in Jersey), is exempt from tax.\n(9) Interest income received in Singapore by Frasers Commercial (UK) Sub. 1 Pte. Ltd. on or after 16 September 2020 from Farnborough Business Park Ltd, is exempt from tax.\n(10) Interest income received in Singapore by British & Malayan Trustees Limited in its capacity as the trustee of Frasers Commercial Trust on or after 15 October 2020 from Frasers Commercial Investments No. 4 Pty Ltd, is exempt from tax.\n(11) The exemptions in sub‑paragraphs (1) to (9) are subject to the conditions specified in the letter from the Ministry of Finance dated 16 September 2020 addressed to EY Corporate Advisors Pte. Ltd.\n(12) The exemption in sub‑paragraph (10) is subject to the conditions specified in the letter from the Ministry of Finance dated 15 October 2020 addressed to EY Corporate Advisors Pte. Ltd."}}],"pack":"sg-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Frasers Commercial Investments No. 1 Pte. Ltd., etc. — Section 13(12) Exemption) Order 2022","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
